function makeDate(timestampOrMonth: number, day?: number, year?: number): Date {
  return day === undefined || year === undefined
    ? new Date(timestampOrMonth)
    : new Date(year, timestampOrMonth, day);
}

const timestampDate = makeDate(12345678);
const calendarDate = makeDate(5, 5, 2024);

