type Container<T> = { get(): T; set(value: T): void };

example.code:
type Animal = { name: string };
type Dog = Animal & { bark(): void };

type Producer<T> = () => T;
type Consumer<T> = (value: T) => void;
type Box<T> = { get(): T; set(value: T): void };

const dogProducer: Producer<Dog> = () => ({
  name: "Rex",
  bark() {}
});
const animalProducer: Producer<Animal> = dogProducer;

const animalConsumer: Consumer<Animal> = animal => console.log(animal.name);
const dogConsumer: Consumer<Dog> = animalConsumer;

const dogBox: Box<Dog> = {
  get: dogProducer,
  set: dog => dog.bark()
};
// const animalBox: Box<Animal> = dogBox; // Error

console.log(animalProducer().name);
dogConsumer({ name: "Milo", bark() {} });
